mapper.select:
SELECT 

WHERE 1 = 1

    AND (
        task.task_no LIKE CONCAT('%', #{keyword}, '%')
        OR meter.meter_no LIKE CONCAT('%', #{keyword}, '%')
        OR meter.meter_name LIKE CONCAT('%', #{keyword}, '%')
    )


    AND result.source_type = #{sourceType}


    AND result.review_status = #{reviewStatus}


    AND result.submitted_at >= #{submittedAtStart}


    AND result.submitted_at <= #{submittedAtEnd}

ORDER BY result.submitted_at DESC, result.id DESC

SELECT COALESCE(MAX(attempt_no), 0) + 1
FROM meter_reading_result
WHERE task_id = #{taskId}
